/**
 * Test load balancer configuration read from a configuration file.
 */
@Test
public void testConfiguration() {
    try {
        String validationError = "Load balancer configuration validation failed";
        URL resourceUrl = this.getClass().getResource(configPath + File.separator + "loadbalancer1.conf");
        File configFile = new File(resourceUrl.getFile());
        System.setProperty("loadbalancer.conf.file", configFile.getAbsolutePath());
        LoadBalancerConfiguration configuration = LoadBalancerConfiguration.getInstance();
        Assert.assertEquals(String.format("%s, algorithm not valid", validationError), "round-robin", configuration.getDefaultAlgorithmName());
        Assert.assertTrue(String.format("%s, failover is not true", validationError), configuration.isFailOverEnabled());
        Assert.assertTrue(String.format("%s, session affinity is not true", validationError), configuration.isSessionAffinityEnabled());
        Assert.assertEquals(String.format("%s, session timeout is not valid", validationError), 90000, configuration.getSessionTimeout());
        Assert.assertTrue(String.format("%s, topology event listener is not true", validationError), configuration.isTopologyEventListenerEnabled());
        Assert.assertEquals(String.format("%s, topology service filter is not valid", validationError), "service-name=service-name1,service-name2", configuration.getTopologyServiceFilter());
        Assert.assertEquals(String.format("%s, topology cluster filter is not valid", validationError), "cluster-id=cluster-id1,cluster-id2", configuration.getTopologyClusterFilter());
        Assert.assertEquals(String.format("%s, topology member filter is not valid", validationError), "lb-cluster-id=lb-cluster-id1", configuration.getTopologyMemberFilter());
        Assert.assertEquals(String.format("%s, mb ip is not valid", validationError), "localhost", configuration.getMbIp());
        Assert.assertEquals(String.format("%s, mb port is not valid", validationError), 5677, configuration.getMbPort());
        Assert.assertTrue(String.format("%s, cep stats publisher is not true", validationError), configuration.isCepStatsPublisherEnabled());
        Assert.assertEquals(String.format("%s, cep ip is not valid", validationError), "localhost", configuration.getCepIp());
        Assert.assertEquals(String.format("%s, cep port is not valid", validationError), 7615, configuration.getCepPort());
        Assert.assertEquals(String.format("%s, network partition id is not valid", validationError), "network-partition-1", configuration.getNetworkPartitionId());
        Assert.assertTrue(String.format("%s, multi-tenancy is not true", validationError), configuration.isMultiTenancyEnabled());
        Assert.assertEquals(String.format("%s, tenant-identifier is not valid", validationError), TenantIdentifier.TenantDomain, configuration.getTenantIdentifier());
        Assert.assertEquals(String.format("%s, tenant-identifier-regex is not valid", validationError), "t/([^/]*)/", configuration.getTenantIdentifierRegex());
    } finally {
        LoadBalancerConfiguration.clear();
    }
}

/**
 * Test static topology configuration read from a file
 */
@Test
public final void testStaticTopology() {
    URL resourceUrl = this.getClass().getResource(configPath + File.separator + "loadbalancer2.conf");
    File configFile = new File(resourceUrl.getFile());
    System.setProperty("loadbalancer.conf.file", configFile.getAbsolutePath());
    LoadBalancerConfiguration.getInstance();
    try {
        String validationError = "Static topology validation failed";
        TopologyManager.acquireReadLock();
        Topology topology = TopologyManager.getTopology();
        Assert.assertTrue(String.format("%s, services not found", validationError), topology.getServices().size() > 0);
        String serviceName = "app-server";
        Service appServer = topology.getService(serviceName);
        Assert.assertNotNull(String.format("%s, service not found: [service] %s", validationError, serviceName), appServer);
        Assert.assertTrue(String.format("%s, multi-tenant is not true: [service] %s", validationError, serviceName), appServer.getServiceType() == ServiceType.MultiTenant);
        String clusterId = "app-server-cluster1";
        Cluster cluster1 = appServer.getCluster(clusterId);
        Assert.assertNotNull(String.format("%s, cluster not found: [cluster] %s", validationError, clusterId), cluster1);
        Assert.assertEquals(String.format("%s, tenant range is not valid: [cluster] %s", validationError, clusterId), cluster1.getTenantRange(), "1-100");
        String hostName = "cluster1.appserver.foo.org";
        Assert.assertTrue(String.format("%s, hostname not found: [hostname] %s", validationError, hostName), hostNameExist(cluster1, hostName));
        hostName = "cluster1.org";
        Assert.assertTrue(String.format("%s, hostname not found: [hostname] %s", validationError, hostName), hostNameExist(cluster1, hostName));
        Assert.assertEquals(String.format("%s, algorithm not valid", validationError), "round-robin", cluster1.getLoadBalanceAlgorithmName());
        String memberId = "m1";
        Member m1 = cluster1.getMember(memberId);
        Assert.assertNotNull(String.format("%s, member not found: [member] %s", validationError, memberId), m1);
        Assert.assertEquals(String.format("%s, member ip not valid", validationError), "10.0.0.10", m1.getMemberIp());
        int proxyPort = 80;
        Port m1Http = m1.getPort(proxyPort);
        Assert.assertNotNull(String.format("%s, port not found: [member] %s [proxy-port] %d", validationError, memberId, proxyPort), m1Http);
        Assert.assertEquals(String.format("%s, port value not valid: [member] %s [proxy-port] %d", validationError, memberId, proxyPort), 8080, m1Http.getValue());
        Assert.assertEquals(String.format("%s, port proxy not valid: [member] %s [proxy-port] %d", validationError, memberId, proxyPort), 80, m1Http.getProxy());
    } finally {
        TopologyManager.releaseReadLock();
        LoadBalancerConfiguration.clear();
    }
}

/**
 * Test in-flight request count calculation.
 */
@Test
public void testInFlightRequestCountCalculation() {
    String clusterId = "cluster1";
    String incrementErrorMessage = "Could not increment in-flight request count: ";
    String decrementErrorMessage = "Could not decrement in-flight request count: ";
    FutureTask<Object> task = new FutureTask<Object>(new InFlightRequestIncrementCallable(clusterId));
    executeTask(task);
    Assert.assertEquals(incrementErrorMessage, 1, LoadBalancerStatisticsCollector.getInstance().getInFlightRequestCount(clusterId));
    task = new FutureTask<Object>(new InFlightRequestIncrementCallable(clusterId));
    executeTask(task);
    Assert.assertEquals(incrementErrorMessage, 2, LoadBalancerStatisticsCollector.getInstance().getInFlightRequestCount(clusterId));
    task = new FutureTask<Object>(new InFlightRequestIncrementCallable(clusterId));
    executeTask(task);
    Assert.assertEquals(incrementErrorMessage, 3, LoadBalancerStatisticsCollector.getInstance().getInFlightRequestCount(clusterId));
    task = new FutureTask<Object>(new InFlightRequestDecrementCallable(clusterId));
    executeTask(task);
    Assert.assertEquals(decrementErrorMessage, 2, LoadBalancerStatisticsCollector.getInstance().getInFlightRequestCount(clusterId));
    task = new FutureTask<Object>(new InFlightRequestDecrementCallable(clusterId));
    executeTask(task);
    Assert.assertEquals(decrementErrorMessage, 1, LoadBalancerStatisticsCollector.getInstance().getInFlightRequestCount(clusterId));
    task = new FutureTask<Object>(new InFlightRequestDecrementCallable(clusterId));
    executeTask(task);
    Assert.assertEquals(decrementErrorMessage, 0, LoadBalancerStatisticsCollector.getInstance().getInFlightRequestCount(clusterId));
    LoadBalancerStatisticsCollector.clear();
}

@Test
public final void testFilterIncluded() {
    String filterName = "filter1";
    String validationError = "MessageFilter.included() method failed";
    System.setProperty(filterName, "property1=value1,value2 | property2=value3,value4");
    MessageFilter messageFilter = new MessageFilter(filterName);
    Assert.assertTrue(validationError, messageFilter.included("property1", "value1"));
    Assert.assertTrue(validationError, messageFilter.included("property1", "value2"));
    Assert.assertTrue(validationError, messageFilter.included("property2", "value3"));
    Assert.assertTrue(validationError, messageFilter.included("property2", "value4"));
    System.setProperty(filterName, "");
}

@Test
public final void testFilterExcluded() {
    String filterName = "filter2";
    String validationError = "MessageFilter.excluded() method failed";
    System.setProperty(filterName, "property1=value1,value2 | property2=value3,value4");
    MessageFilter messageFilter = new MessageFilter(filterName);
    Assert.assertFalse(validationError, messageFilter.excluded("property1", "value1"));
    Assert.assertFalse(validationError, messageFilter.excluded("property1", "value2"));
    Assert.assertFalse(validationError, messageFilter.excluded("property2", "value3"));
    Assert.assertFalse(validationError, messageFilter.excluded("property2", "value4"));
    System.setProperty(filterName, "");
}

@Test
public final void testFilterGetAllPropertyValues() {
    String filterName = "filter2";
    String validationError = "MessageFilter.getIncludedPropertyValues() method failed";
    System.setProperty(filterName, "property1=value1,value2 | property2=value3,value4");
    MessageFilter messageFilter = new MessageFilter(filterName);
    Collection<String> property1Values = messageFilter.getIncludedPropertyValues("property1");
    Assert.assertTrue(validationError, property1Values.contains("value1"));
    Assert.assertTrue(validationError, property1Values.contains("value2"));
    Collection<String> property2Values = messageFilter.getIncludedPropertyValues("property2");
    Assert.assertTrue(validationError, property2Values.contains("value3"));
    Assert.assertTrue(validationError, property2Values.contains("value4"));
    System.setProperty(filterName, "");
}

@Test
public void testSubscriptionModel() {
    Tenant tenant = new Tenant(1, "domain.org");
    Subscription subscription = new Subscription("subscription1", new HashSet<String>());
    tenant.addSubscription(subscription);
    Assert.assertTrue("Subscription not added", tenant.isSubscribed("subscription1"));
    tenant.removeSubscription("subscription1");
    Assert.assertTrue("Subscription not removed", !tenant.isSubscribed("subscription1"));
}

