@Test
public void testMapEBS() throws Exception {
    if (ebsTemplate == null) {
        throw new SkipException("Test cannot run without the parameter test." + provider + ".ebs-template; this property should be in the format defined in TemplateBuilderSpec");
    }
    InstanceApi instanceClient = view.unwrapApi(EC2Api.class).getInstanceApi().get();
    ElasticBlockStoreApi ebsClient = view.unwrapApi(EC2Api.class).getElasticBlockStoreApi().get();
    String group = this.group + "e";
    int volumeSize = 8;
    final Template template = view.getComputeService().templateBuilder().from(ebsTemplate).build();
    Location zone = Iterables.find(view.getComputeService().listAssignableLocations(), new Predicate<Location>() {

        @Override
        public boolean apply(Location arg0) {
            return arg0.getScope() == LocationScope.ZONE && arg0.getParent().getId().equals(template.getLocation().getId());
        }
    });
    // create volume only to make a snapshot
    Volume volume = ebsClient.createVolumeInAvailabilityZone(zone.getId(), 4);
    // Sleep for 5 seconds to make sure the volume creation finishes.
    Thread.sleep(5000);
    Snapshot snapshot = ebsClient.createSnapshotInRegion(volume.getRegion(), volume.getId());
    ebsClient.deleteVolumeInRegion(volume.getRegion(), volume.getId());
    //
    template.getOptions().as(EC2TemplateOptions.class).// .unmapDeviceNamed("/dev/foo)
    mapEphemeralDeviceToDeviceName("/dev/sdm", //
    "ephemeral0").mapNewVolumeToDeviceName("/dev/sdn", volumeSize, //
    true).mapEBSSnapshotToDeviceName("/dev/sdo", snapshot.getId(), volumeSize, true);
    try {
        NodeMetadata node = Iterables.getOnlyElement(client.createNodesInGroup(group, 1, template));
        // TODO figure out how to validate the ephemeral drive. perhaps with df -k?
        Map<String, BlockDevice> devices = instanceClient.getBlockDeviceMappingForInstanceInRegion(node.getLocation().getParent().getId(), node.getProviderId());
        BlockDevice device = devices.get("/dev/sdn");
        // check delete on termination
        assertTrue(device.isDeleteOnTermination());
        volume = Iterables.getOnlyElement(ebsClient.describeVolumesInRegion(node.getLocation().getParent().getId(), device.getVolumeId()));
        // check volume size
        assertEquals(volumeSize, volume.getSize());
        device = devices.get("/dev/sdo");
        // check delete on termination
        assertTrue(device.isDeleteOnTermination());
        volume = Iterables.getOnlyElement(ebsClient.describeVolumesInRegion(node.getLocation().getParent().getId(), device.getVolumeId()));
        // check volume size
        assertEquals(volumeSize, volume.getSize());
        // check volume's snapshot id
        assertEquals(snapshot.getId(), volume.getSnapshotId());
    } finally {
        client.destroyNodesMatching(NodePredicates.inGroup(group));
        ebsClient.deleteSnapshotInRegion(snapshot.getRegion(), snapshot.getId());
    }
}

@Test
public void testTemplateBuilderCanUseImageIdWithoutFetchingAllImages() throws Exception {
    Template defaultTemplate = view.getComputeService().templateBuilder().build();
    String defaultImageId = defaultTemplate.getImage().getId();
    String defaultImageProviderId = defaultTemplate.getImage().getProviderId();
    ComputeServiceContext context = null;
    try {
        // Track http commands
        final List<HttpCommand> commandsInvoked = Lists.newArrayList();
        context = createView(setupProperties(), ImmutableSet.<Module>of(new Log4JLoggingModule(), TrackingJavaUrlHttpCommandExecutorService.newTrackingModule(commandsInvoked)));
        Template template = context.getComputeService().templateBuilder().imageId(defaultImageId).build();
        assertEquals(template.getImage(), defaultTemplate.getImage());
        Collection<HttpCommand> filteredCommandsInvoked = Collections2.filter(commandsInvoked, new Predicate<HttpCommand>() {

            private final Collection<Method> ignored = ImmutableSet.of(AvailabilityZoneAndRegionApi.class.getMethod("describeRegions", DescribeRegionsOptions[].class), AvailabilityZoneAndRegionApi.class.getMethod("describeAvailabilityZonesInRegion", String.class, DescribeAvailabilityZonesOptions[].class));

            @Override
            public boolean apply(HttpCommand input) {
                return !ignored.contains(getInvokerOfRequest(input));
            }
        });
        assert filteredCommandsInvoked.size() == 1 : commandsInvoked;
        assertEquals(getInvokerOfRequestAtIndex(filteredCommandsInvoked, 0), AMIApi.class.getMethod("describeImagesInRegion", String.class, DescribeImagesOptions[].class));
        assertDescribeImagesOptionsEquals((DescribeImagesOptions[]) getArgsForRequestAtIndex(filteredCommandsInvoked, 0).get(1), defaultImageProviderId);
    } finally {
        if (context != null)
            context.close();
    }
}

